def retain_extremes(stack):
    first = stack.pop()
    smallest = largest = first
    while not stack.isEmpty():
        value = stack.pop()
        if value < smallest:
            smallest = value
        if value > largest:
            largest = value
    stack.push(largest)
    stack.push(smallest)

